<template>
<div class="research-factory">
  <section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="pulse"></span> TENSOR RESEARCH INFRASTRUCTURE</div><h1>科研工厂 <span>Research Factory</span></h1><p>以 Agent 为科研主体，统一组织研究目标、真实计算任务、运行产物和验证证据。当前可执行本地 CPU 数值基准；HPC 与 Tensor 求解器按真实接入状态呈现。</p><div class="hero-actions"><el-button type="primary" size="large" @click="showCreate=true"><el-icon><Plus/></el-icon>发起计算任务</el-button><el-button size="large" plain @click="loadTasks"><el-icon><Refresh/></el-icon>刷新任务</el-button></div></div><div class="hero-orbit"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit-core"><el-icon><Cpu/></el-icon><strong>Agent</strong><small>科研主体</small></div><div class="orbit-node node-a">目标</div><div class="orbit-node node-b">计算</div><div class="orbit-node node-c">证据</div></div><div class="environment-tag"><span class="dot"></span>{{ healthLabel }}</div></section>
  <el-alert v-if="pageError" class="page-error" type="error" show-icon :closable="true" :title="pageError" @close="pageError=''"/>
  <section class="metrics"><div class="metric-card"><div class="metric-label">持久化任务</div><div class="metric-value">{{tasks.length}}</div><div class="metric-foot">后端数据库</div></div><div class="metric-card"><div class="metric-label">计算已完成</div><div class="metric-value">{{completedCount}}</div><div class="metric-foot">真实执行本地数值积分</div></div><div class="metric-card"><div class="metric-label">等待执行</div><div class="metric-value">{{queuedCount}}</div><div class="metric-foot">可启动运行</div></div><div class="metric-card"><div class="metric-label">HPC 调度</div><div class="metric-value status-text">{{hpcConnected?'已连接':'未连接'}}</div><div class="metric-foot">当前不会提交集群作业</div></div></section>
  <section class="section-block"><div class="section-heading"><div><div class="section-kicker">RUNNABLE COMPUTE</div><h2>当前可执行的计算能力</h2><p>阻尼弹簧链 CPU 数值基准用于验证任务生命周期、计算、产物与 API 闭环；它不是破冰 DEM 物理模型。</p></div><el-tag type="success" effect="plain">Local CPU Runner</el-tag></div><div class="capability"><div class="cap-icon"><el-icon><DataAnalysis/></el-icon></div><div class="cap-copy"><strong>阻尼弹簧链动力学基准 v1</strong><p>固定端点、弹簧相互作用、阻尼项与中心脉冲；显式时间积分，生成位移/能量 CSV 和运行清单 JSON。</p><div class="cap-tags"><el-tag size="small">真实数值计算</el-tag><el-tag size="small" type="info">CPU / 本地</el-tag><el-tag size="small" type="warning">非 TensorDEM</el-tag></div></div><el-button type="primary" plain @click="showCreate=true">运行基准</el-button></div>
  <div class="solver-grid"><div v-for="s in solvers" :key="s.name" class="solver-card"><div class="solver-mark" :class="s.tone">{{s.short}}</div><div class="solver-info"><strong>{{s.name}}</strong><p>{{s.role}}</p><span>{{s.status}}</span></div><el-tag size="small" :type="s.available?'success':'info'" effect="plain">{{s.available?'可执行':'待接入'}}</el-tag></div></div></section>
  <section class="section-block"><div class="section-heading"><div><div class="section-kicker">EXPERIMENT REGISTRY</div><h2>科研运行记录</h2><p>任务写入后端 SQLite 持久化存储；刷新页面后仍可查询。计算结果可查看和下载。</p></div><el-button @click="loadTasks" :loading="loading"><el-icon><Refresh/></el-icon>刷新</el-button></div>
  <el-table :data="tasks" v-loading="loading" row-key="id" class="task-table" empty-text="暂无任务。创建任务后点击“执行计算”。"><el-table-column label="科研任务" min-width="250"><template #default="{row}"><div class="task-name">{{row.title}}</div><div class="task-sub">{{row.id}} · {{row.solver}}</div></template></el-table-column><el-table-column label="状态" min-width="110"><template #default="{row}"><el-tag :type="stateType(row.status)">{{stateLabel(row.status)}}</el-tag></template></el-table-column><el-table-column label="后端" min-width="110"><template #default="{row}"><span class="env-pill">{{row.backend}}</span></template></el-table-column><el-table-column label="验证边界" min-width="165"><template #default="{row}"><span class="verification">{{verificationLabel(row.verification)}}</span></template></el-table-column><el-table-column label="创建时间" min-width="175"><template #default="{row}">{{formatDate(row.created_at)}}</template></el-table-column><el-table-column label="操作" min-width="205" fixed="right"><template #default="{row}"><el-button text type="primary" @click="openTask(row)">结果 / 日志</el-button><el-button v-if="row.status==='queued'||row.status==='failed'" text type="success" :loading="runningId===row.id" @click="runTask(row)">执行计算</el-button></template></el-table-column></el-table></section>
  <el-dialog v-model="showCreate" title="创建可执行科研任务" width="min(680px,94vw)" destroy-on-close><div class="dialog-intro">任务会写入后端数据库。当前仅开放 SpringChainBenchmark 执行器；TensorDEM、TensorLBM、TensorFEM 尚未在 Harness 注册真实进程适配器。</div><el-form label-position="top" :model="form"><el-form-item label="科研任务名称" required><el-input v-model="form.title" maxlength="160"/></el-form-item><el-form-item label="研究目标 / 假设"><el-input v-model="form.goal" type="textarea" :rows="3" maxlength="4000"/></el-form-item><el-divider content-position="left">计算参数</el-divider><el-row :gutter="14"><el-col :span="12"><el-form-item label="粒子数 8–64"><el-input-number v-model="form.particles" :min="8" :max="64"/></el-form-item></el-col><el-col :span="12"><el-form-item label="积分步数 100–10000"><el-input-number v-model="form.steps" :min="100" :max="10000" :step="100"/></el-form-item></el-col><el-col :span="12"><el-form-item label="时间步长 dt"><el-input-number v-model="form.dt" :min="0.0001" :max="0.003" :step="0.0001" :precision="4"/></el-form-item></el-col><el-col :span="12"><el-form-item label="弹簧刚度"><el-input-number v-model="form.spring_stiffness" :min="10" :max="1000" :step="10"/></el-form-item></el-col></el-row><el-alert title="科学有效性声明" type="warning" :closable="false" show-icon description="此执行器是通用动力学基准，不等同于冰层键合颗粒 DEM；计算成功不代表独立基准验证通过。"/></el-form><template #footer><el-button @click="showCreate=false">取消</el-button><el-button type="primary" :loading="creating" :disabled="form.title.trim().length<2" @click="createTask(false)">创建任务</el-button><el-button type="success" :loading="creating" :disabled="form.title.trim().length<2" @click="createTask(true)">创建并执行</el-button></template></el-dialog>
  <el-drawer v-model="detailVisible" title="运行结果与产物" size="min(680px,96vw)"><template v-if="selectedTask"><div class="detail-banner"><span class="detail-label">RUN ID · {{selectedTask.id}}</span><h3>{{selectedTask.title}}</h3><p>{{selectedTask.goal||'未提供研究描述。'}}</p><div class="detail-tags"><el-tag :type="stateType(selectedTask.status)">{{stateLabel(selectedTask.status)}}</el-tag><el-tag effect="plain">{{selectedTask.backend}}</el-tag><el-tag type="warning" effect="plain">科学验证未建立</el-tag></div></div><div v-if="selectedTask.result" class="result-grid"><div class="result-card"><span>峰值位移</span><strong>{{number(selectedTask.result.peak_displacement)}}</strong></div><div class="result-card"><span>最终总能量</span><strong>{{number(selectedTask.result.final_total_energy)}}</strong></div><div class="result-card"><span>模拟时间</span><strong>{{number(selectedTask.result.simulated_time)}} s</strong></div><div class="result-card"><span>计算耗时</span><strong>{{number(selectedTask.result.wall_time_seconds)}} s</strong></div></div><template v-if="selectedTask.result"><h4>时间序列结果（前 12 个采样点）</h4><el-table :data="selectedTask.result.samples.slice(0,12)" size="small" max-height="300"><el-table-column prop="time" label="时间 (s)"/><el-table-column prop="max_abs_displacement" label="最大位移"/><el-table-column prop="kinetic_energy" label="动能"/><el-table-column prop="elastic_energy" label="弹性势能"/></el-table><h4>计算产物</h4><div class="artifact-row"><el-icon><Document/></el-icon><div><strong>timeseries.csv</strong><p>位移与能量时间序列。</p><p class="artifact-integrity">{{artifactSummary("timeseries.csv")}}</p></div><el-button size="small" @click="downloadArtifact('timeseries.csv')">下载 CSV</el-button></div><div class="artifact-row"><el-icon><Document/></el-icon><div><strong>run-manifest.json</strong><p>任务参数、结果摘要和验证边界。</p><p class="artifact-integrity">{{artifactSummary("run-manifest.json")}}</p></div><el-button size="small" @click="downloadArtifact('run-manifest.json')">下载清单</el-button></div></template><el-alert v-else title="尚无计算结果" type="info" :closable="false" description="任务已保存但尚未完成计算。"/></template><el-alert class="detail-alert" title="结果边界" type="warning" :closable="false" show-icon description="后端真实执行并生成数据文件；目前仅完成有限值检查，不代表物理正确性或数值收敛性验证，也不能声称破冰阻力预测有效。"/></el-drawer>
</div>
</template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {Cpu,DataAnalysis,Document,Plus,Refresh} from '@element-plus/icons-vue'
import http from '@/api/request'
type Sample={time:number;max_abs_displacement:number;kinetic_energy:number;elastic_energy:number;total_energy:number}
type Artifact={name:string;url:string;media_type:string;sha256:string;size_bytes:number}
type Result={peak_displacement:number;final_total_energy:number;simulated_time:number;wall_time_seconds:number;samples:Sample[];artifacts?:Artifact[]}
type Task={id:string;title:string;goal:string;solver:string;backend:string;status:string;verification:string;created_at:string;parameters:Record<string,number>;result:Result|null;error?:string}
const tasks=ref<Task[]>([]),loading=ref(false),creating=ref(false),runningId=ref(''),pageError=ref(''),showCreate=ref(false),detailVisible=ref(false),selectedTask=ref<Task|null>(null),hpcConnected=ref(false),healthLabel=ref('正在检查后端...')
const form=reactive({title:'阻尼弹簧链动力学与能量演化基准',goal:'验证任务持久化、CPU 数值执行、时间序列产物和运行清单的端到端流程。',particles:24,steps:2400,dt:0.001,spring_stiffness:180})
const completedCount=computed(()=>tasks.value.filter(t=>t.status==='completed').length),queuedCount=computed(()=>tasks.value.filter(t=>t.status==='queued').length)
const solvers=[{name:'SpringChainBenchmark',short:'CPU',role:'阻尼弹簧链数值积分与时间序列输出',status:'后端已实现',available:true,tone:'green'},{name:'TensorDEM',short:'DEM',role:'键合颗粒、断键与接触破坏',status:'需要真实进程适配器',available:false,tone:'violet'},{name:'TensorLBM',short:'LBM',role:'流体求解与流固耦合',status:'需要真实进程适配器',available:false,tone:'blue'},{name:'TensorFEM',short:'FEM',role:'结构响应与有限元分析',status:'需要真实进程适配器',available:false,tone:'amber'}]
function stateType(s:string){return s==='completed'?'success':s==='failed'?'danger':s==='running'?'warning':'info'}
function stateLabel(s:string){return ({queued:'等待执行',running:'运行中',completed:'计算完成',failed:'执行失败'} as Record<string,string>)[s]||s}
function verificationLabel(v:string){return v==='computed-not-scientifically-validated'?'已计算 / 未独立验证':v==='not-validated'?'未验证':v}
function formatDate(v:string){return v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'}
function number(v:number|undefined){return typeof v==='number'?v.toExponential(3):'—'}
function artifactSummary(name:string){const item=selectedTask.value?.result?.artifacts?.find(a=>a.name===name);return item?'SHA-256 '+item.sha256+' · '+item.size_bytes+' bytes':'完整性信息暂不可用'}
async function checkHealth(){try{const h=await http.get('/research-factory/health');hpcConnected.value=Boolean(h.hpc?.connected);healthLabel.value='后端已连接 · SQLite 持久化 · Local CPU Runner'}catch{healthLabel.value='后端不可用';pageError.value='科研工厂 API 无法连接，请启动 TensorPlatform backend 并检查 /api/v1/research-factory/health。'}}
async function loadTasks(){loading.value=true;try{const data=await http.get('/research-factory/tasks');tasks.value=data.items||[]}catch(e:any){pageError.value=e?.message||'加载任务失败'}finally{loading.value=false}}
async function createTask(run:boolean){creating.value=true;try{const task=await http.post('/research-factory/tasks',{title:form.title,goal:form.goal,solver:'SpringChainBenchmark',backend:'local-cpu',parameters:{particles:form.particles,steps:form.steps,dt:form.dt,spring_stiffness:form.spring_stiffness}});showCreate.value=false;await loadTasks();ElMessage.success('任务已持久化到后端');if(run)await runTask(task);else await openTask(task)}catch(e:any){pageError.value=e?.message||'创建任务失败'}finally{creating.value=false}}
async function runTask(task:Task){runningId.value=task.id;try{const done=await http.post('/research-factory/tasks/'+encodeURIComponent(task.id)+'/run');const i=tasks.value.findIndex(t=>t.id===done.id);if(i>=0)tasks.value[i]=done;else tasks.value.unshift(done);selectedTask.value=done;detailVisible.value=true;ElMessage.success('CPU 数值计算完成，结果文件已生成')}catch(e:any){pageError.value=e?.message||'计算执行失败';await loadTasks()}finally{runningId.value=''}}
async function openTask(task:Task){try{selectedTask.value=await http.get('/research-factory/tasks/'+encodeURIComponent(task.id))}catch{selectedTask.value=task}detailVisible.value=true}
function downloadArtifact(name:string){if(!selectedTask.value)return;window.open('/api/v1/research-factory/tasks/'+encodeURIComponent(selectedTask.value.id)+'/artifacts/'+encodeURIComponent(name),'_blank','noopener')}
onMounted(async()=>{await checkHealth();await loadTasks()})
</script>
<style scoped lang="scss">
